  ShSyms.strlen = 0xa30 /\
  ShSyms.strchr = 0xa82 /\
  ShSyms.malloc = 0x118c /\
  ShSyms.free = 0x1106 /\
  ShSyms.sbrk = 0xc52 /\
  ShSyms.read = 0xc9e /\
  ShSyms.write = 0xca6 /\
  ShSyms.open = 0xcc6 /\
  ShSyms.close = 0xcae /\
  ShSyms.fork = 0xc7e /\
  ShSyms.wait = 0xc8e /\
  ShSyms.exec = 0xcbe /\
  ShSyms.exit = 0xc86 /\
  ShSyms.sys_sbrk = 0xd0e.
Proof.
  unfold ShSyms.start,
         ShSyms.main,
         ShSyms.getcmd,
         ShSyms.gets,
         ShSyms.runcmd,
         ShSyms.fork1,
         ShSyms.execcmd,
         ShSyms.parsecmd,
         ShSyms.parseline,
         ShSyms.parsepipe,
         ShSyms.parseexec,
         ShSyms.parseredirs,
         ShSyms.peek,
         ShSyms.gettoken,
         ShSyms.nulterminate,
         ShSyms.memset,
         ShSyms.strlen,
         ShSyms.strchr,
         ShSyms.malloc,
         ShSyms.free,
         ShSyms.sbrk,
         ShSyms.read,
         ShSyms.write,
         ShSyms.open,
         ShSyms.close,
         ShSyms.fork,
         ShSyms.wait,
         ShSyms.exec,
         ShSyms.exit,
         ShSyms.sys_sbrk.
  split_and!; reflexivity.
Qed.

(* ===================================================================== *)
(* §1 Per-WORD decode facts.                                              *)
(* ===================================================================== *)

(* One lemma per DISTINCT word (630 of them for 1032 instructions), reused
   at every pc where that word occurs.

   Base words: the concrete-state bridge at [dstateU] (WpDecodeBridge),
   transported to any state agreeing with it on the U-mode decode read set
   [D_u] -- exactly the [udecode_base] shape [uinstr] wants. The closing
   step descends the AST with [f_equal] and finishes each bitvector leaf
   with [bv_eq] (a bare [reflexivity] would have to match well-formedness
   proof terms).

   Compressed words: [rvc_oneshot] under the misa.C premise. *)

Ltac udec_base_bridge :=
  let s := fresh "s" in let Hag := fresh "Hag" in
  intros s Hag;
  apply (decode_state_bridge D_u _ dstateU);
  [ exact Hag
  | vm_compute; reflexivity
  | vm_compute; repeat first [ reflexivity | (apply bv_eq; vm_compute; reflexivity) | f_equal ] ].

Ltac udec_rvc_oneshot :=
  let s := fresh "s" in let Hm := fresh "Hm" in intros s Hm; rvc_oneshot s Hm.

